window.TADABBUR_FATIR = {"_meta":{"description":"تدبّرٌ مُسنَد لسورة فاطر (٣٥)، سورةٌ مكّيّةٌ محورُها حمدُ الله فاطرِ السماواتِ والأرض، وفضلُه ورحمتُه، وآياتُ القدرةِ والنعمة، ودعوةُ الناسِ إلى شكرِ الله وترْكِ عبادةِ ما سواه، وميراثُ الكتابِ في الأمّة؛ فيها «الحمد لله فاطر السماوات والأرض» و«يا أيها الناس أنتم الفقراء إلى الله». بُدئت بالحمد. كلُّ آيةٍ مغطّاةٍ تحمل وقفةً مُسنَدةً موسومة (ابن كثير/السعدي).","honesty":"لا نُقدّم شيئًا كإعجازٍ مُثبَت؛ المعنى منقولٌ بتصرّفٍ يسير من التفسيرين بإحالةٍ صريحة، والنصُّ القرآنيُّ يُؤخذ من المورفولوجيا وقتَ العرض."},"n":35,"name":"فاطر","total_ayahs":45,"audio":[1,3,10,15,18,28,29,32,34,45],"passages":[{"title":"حمدُ الله الفاطرِ ورحمتُه، والدعوةُ إلى شكرِه والحذرِ من الغرور","range":[1,6],"theme":"حمدُ الله فاطرِ الكونِ وجاعلِ الملائكةِ رسلًا، وأنّ الرحمةَ والمنعَ بيده، والأمرُ بذكرِ نعمِه والاستدلالِ بها على التوحيد، وتسليةُ النبيِّ في التكذيب، والتحذيرُ من غرورِ الدنيا والشيطان، والأمرُ بمعاداةِ الشيطان","verses":[{"n":1,"reflection":{"text":"«الحمد لله فاطر السماوات والأرض جاعل الملائكة رسلا أولي أجنحة مثنى وثلاث ورباع يزيد في الخلق ما يشاء إن الله على كل شيء قدير» — الحمدُ لله مبدعِ السماواتِ والأرضِ على غيرِ مثال، جاعلِ الملائكةِ رسلًا لهم أجنحةٌ اثنان وثلاثةٌ وأربعة، يزيد في الخلقِ ما يشاء، إنّ الله على كلِّ شيءٍ قدير؛ ففي هذا حمدُ الله على بديعِ خلقه وقدرته؛ فاحمد الله فاطرَ الكونِ وبديعَ خلقه، فهو القادرُ على كلِّ شيء، فمن رأى بديعَ خلقِ الله حمده وعظّمه، فاجعل الحمدَ دأبك، معترفًا بقدرةِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["القدير"],"heart_state":{"text":"حمدُ الله على بديعِ خلقه وقدرته المطلقة."},"action":{"text":"احمد الله فاطرَ السماواتِ والأرض، مبدعَهما على غيرِ مثالٍ سابق؛ وتأمّل بديعَ خلقه، حتى الملائكةَ جعلهم رسلًا بأجنحةٍ متفاوتة، ويزيد في الخلقِ ما يشاء «إن الله على كل شيء قدير»؛ فمن تأمّل بديعَ خلقِ الله وقدرته المطلقةِ حمده وعظّمه وأجلّه؛ فاجعل الحمدَ دأب لسانك وقلبك؛ واعترف بقدرةِ الله على كلِّ شيء؛ فلا يعجزه شيء؛ فاطلب حاجتك من القادرِ على كلِّ شيء؛ فمن حمد الله على خلقه وأيقن بقدرته اطمأنَّ قلبه وقوي إيمانه؛ فالحمدُ رأسُ الشكر، ومعرفةُ القدرةِ أساسُ التوكّل."}},{"n":2,"reflection":{"text":"«ما يفتح الله للناس من رحمة فلا ممسك لها وما يمسك فلا مرسل له من بعده وهو العزيز الحكيم» — ما يفتح الله للناسِ من رحمةٍ (رزقٍ أو نعمةٍ أو علمٍ) فلا أحدَ يمنعها، وما يمسكه فلا أحدَ يرسله من بعده، وهو العزيزُ الحكيم؛ ففي هذا أنّ الرحمةَ والمنعَ بيدِ الله وحده؛ فاطلب الرحمةَ من الله وحده، فما فتحه لا يمنعه أحد، وما أمسكه لا يعطيه أحد، فتعلّق به وحده، فهو العزيزُ الحكيمُ الذي بيده كلُّ شيء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العزيز","الحكيم"],"heart_state":{"text":"طلبُ الرحمةِ من الله وحده، فالفتحُ والمنعُ بيده."},"action":{"text":"اطلب الرحمةَ والرزقَ والخيرَ من الله وحده، فما يفتحه الله للناسِ من رحمةٍ فلا أحدَ يقدر على منعها، وما يمسكه فلا أحدَ يقدر على إرساله «ما يفتح الله للناس من رحمة فلا ممسك لها»؛ فالفتحُ والمنعُ بيدِ الله وحده؛ فتعلّق به وحده، ولا ترجُ رحمةً من مخلوقٍ ولا تخف منعه؛ فهو العزيزُ الغالبُ الذي لا يُقهَر، الحكيمُ الذي يفتح ويمنع بحكمة؛ فمن أيقن أنّ الرحمةَ بيدِ الله وحده لم يتعلّق قلبه بسواه؛ فاجعل رجاءك في فضلِ الله، وطلبك منه؛ فما قسمه لك لا يمنعه أحد، وما منعه عنك لا يعطيه أحد؛ فارضَ بقسمته، واطلب فضله؛ فهو العزيزُ الحكيمُ الذي بيده مقاليدُ كلِّ شيء."}},{"n":3,"reflection":{"text":"«يا أيها الناس اذكروا نعمة الله عليكم هل من خالق غير الله يرزقكم من السماء والأرض لا إله إلا هو فأنى تؤفكون» — يا أيها الناسُ اذكروا نعمةَ الله عليكم، هل من خالقٍ غيرُ الله يرزقكم من السماءِ والأرض؟ لا معبودَ بحقٍّ إلا هو، فكيف تُصرَفون عن عبادته؟ ففي هذا الأمرُ بذكرِ النعمِ والاستدلالِ بها على التوحيد؛ فاذكر نعمَ الله عليك واشكرها، واعلم أنّ الخالقَ الرازقَ هو الله وحده، فأخلص له العبادة، فمن أقرّ بأنّ الله الخالقُ الرازقُ فليعبده وحده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ذكرُ نعمِ الله والاستدلالُ بها على إفرادِه بالعبادة."},"action":{"text":"اذكر نعمَ الله عليك الظاهرةَ والباطنة، واشكرها بالقلبِ واللسانِ والعمل «اذكروا نعمة الله عليكم»؛ واستدلَّ بها على أنّ الخالقَ الرازقَ من السماءِ والأرضِ هو الله وحده، فلا خالقَ ولا رازقَ سواه؛ فهذا يوجب إفرادَه بالعبادة «لا إله إلا هو»؛ فكيف تُصرَف عن عبادةِ من خلقك ورزقك إلى عبادةِ من لا يخلق ولا يرزق؟ فأخلص عبادتك لله الخالقِ الرازق؛ ولا تعبد سواه؛ فمن أقرّ بأنّ الله خالقه ورازقه لزمه أن يعبده وحده؛ فاجعل ذكرَ النعمِ سبيلًا لشكرِ المنعمِ وإفرادِه بالعبادة؛ فالنعمُ كلُّها منه، فالعبادةُ كلُّها له؛ فلا تصرف عبادتك ولا شكرك لغيره."}},{"n":4,"reflection":{"text":"«وإن يكذبوك فقد كذبت رسل من قبلك وإلى الله ترجع الأمور» — وإن يكذّبك قومك فقد كُذِّبت رسلٌ من قبلك، وإلى الله ترجع الأمورُ كلُّها فيجازي كلًّا بعمله؛ ففي هذا تسليةُ النبيِّ وأنّ التكذيبَ سنّةُ المرسلين؛ فلا يحزنك تكذيبُ المكذّبين، فقد كُذِّب الرسلُ قبلك، واصبر واعلم أنّ الأمورَ ترجع إلى الله، فهو يجازي المكذّبين والمصدّقين، فالعاقبةُ بيدِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على التكذيب، واليقينُ بأنّ الأمورَ ترجع إلى الله."},"action":{"text":"لا يحزنك تكذيبُ المكذّبين لك أو لدعوتك، فذلك سنّةٌ ماضيةٌ في المرسلين، فقد كُذِّبت رسلٌ من قبلك «وإن يكذبوك فقد كذبت رسل من قبلك»؛ فاصبر كما صبروا؛ واعلم أنّ الأمورَ كلَّها ترجع إلى الله، فيجازي المكذّبين بتكذيبهم والمصدّقين بتصديقهم «وإلى الله ترجع الأمور»؛ فلا تحمل همَّ من كذّب أو أعرض؛ فليس عليك إلا البلاغ؛ وكِل أمرهم إلى الله؛ فالعاقبةُ بيدِ الله، وهو يفصل بين الخلقِ يومَ القيامة؛ فامضِ في دعوتك محتسبًا صابرًا؛ فمن صبر على التكذيبِ ووكّل أمره إلى الله كفاه وأيّده؛ فاجعل عزاءك أنّ الأمورَ ترجع إلى الله، وأنّ الحقَّ منصورٌ في النهاية."}},{"n":5,"reflection":{"text":"«يا أيها الناس إن وعد الله حق فلا تغرنكم الحياة الدنيا ولا يغرنكم بالله الغرور» — يا أيها الناسُ إنّ وعدَ الله بالبعثِ والجزاءِ حقٌّ، فلا تخدعنّكم الحياةُ الدنيا وزينتها عن الاستعدادِ للآخرة، ولا يخدعنّكم بالله الشيطانُ الغرور؛ ففي هذا التحذيرُ من غرورِ الدنيا والشيطان؛ فلا تغترَّ بالدنيا فتنسى الآخرة، ولا يخدعنّك الشيطانُ بحلمِ الله وإمهاله، فوعدُ الله حقٌّ، فاستعدَّ للقائه ولا تنخدع.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الغرور"],"heart_state":{"text":"الحذرُ من غرورِ الدنيا والشيطان، والاستعدادُ للقاءِ الله."},"action":{"text":"أيقن بأنّ وعدَ الله بالبعثِ والحسابِ والجزاءِ حقٌّ لا محالة «إن وعد الله حق»؛ فلا تدع الحياةَ الدنيا وزينتها ولذّاتها تخدعك عن الاستعدادِ للآخرة؛ ولا يغرّنّك الشيطانُ بحلمِ الله وإمهاله فتؤجّل التوبةَ وتغترّ بالمعصية؛ فالشيطانُ الغرورُ يخدع الناسَ فيمنّيهم ويسوّف بهم؛ فاحذر خدعتين: غرورَ الدنيا الفانية، وتغريرَ الشيطانِ بطولِ الأمل؛ فاجعل استحضارَ وعدِ الله الحقِّ حاديًا لك إلى العملِ والاستعداد؛ فمن أيقن بوعدِ الله لم يغترَّ بالدنيا ولا بالشيطان؛ فبادر بالتوبةِ والعملِ الصالح؛ ولا تنخدع بزينةِ الدنيا الزائلة ولا بوساوسِ الشيطان؛ فالموفَّقُ من نظر إلى الباقي فآثره على الفاني، ولم يدع شيئًا يغرّه عن ربّه."}},{"n":6,"reflection":{"text":"«إن الشيطان لكم عدو فاتخذوه عدوا إنما يدعو حزبه ليكونوا من أصحاب السعير» — إنّ الشيطانَ لكم عدوٌّ حقيقيٌّ فعادوه واحذروه، إنما يدعو أتباعه إلى الشرِّ ليكونوا من أهلِ النار؛ ففي هذا الأمرُ بمعاداةِ الشيطانِ والحذرِ منه؛ فعادِ الشيطانَ فهو عدوّك، ولا تطعه فيما يدعوك إليه، فإنه لا يريد بك إلا الهلاك، فاتّخذه عدوًّا كما هو لك عدوّ، واحذر أن تكون من حزبه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"معاداةُ الشيطانِ والحذرُ من دعوته إلى الشرّ."},"action":{"text":"عادِ الشيطانَ واتّخذه عدوًّا كما هو لك عدوٌّ حقيقيّ، فلا تطعه ولا تستجب لوسوسته «إن الشيطان لكم عدو فاتخذوه عدوا»؛ فإنه لا يريد بك إلا الهلاك، ولا يدعو أتباعه (حزبه) إلا إلى الشرِّ والمعصيةِ ليكونوا من أصحابِ السعير؛ فاحذر أن تكون من حزبِ الشيطانِ الذين يطيعونه؛ وكن من حزبِ الرحمنِ الذين يطيعون الله؛ فاستعذ بالله من الشيطانِ الرجيمِ دائمًا؛ وخالفه في كلِّ ما يأمرك به؛ فمن عادى الشيطانَ وحذره نجا، ومن اتّبعه هلك؛ فراقب نفسك: أتطيع الله أم تطيع الشيطان؟ فاجعل الشيطانَ عدوَّك الأوّل، وجاهده بمخالفته والاستعاذةِ منه ولزومِ طاعةِ الله؛ فبذلك تنجو من كيده وإغوائه."}}]},{"title":"جزاءُ الفريقين، وآياتُ القدرةِ والنعمة، وعجزُ ما سوى الله","range":[7,14],"theme":"جزاءُ الكافرين بالعذابِ والمؤمنين بالمغفرة، وخطرُ تزيينِ السوء، وإحياءُ الأرضِ دليلَ البعث، وأنّ العزّةَ لله والكلمَ الطيّبَ يصعد إليه، وإحاطةُ علمِه بالخلقِ والأعمار، ونعمُ البحرين، وعجزُ ما يُدعى من دونه عن ملكِ قطمير","verses":[{"n":7,"reflection":{"text":"«الذين كفروا لهم عذاب شديد والذين آمنوا وعملوا الصالحات لهم مغفرة وأجر كبير» — الذين كفروا لهم عذابٌ شديد، والذين آمنوا وعملوا الصالحاتِ لهم مغفرةٌ لذنوبهم وأجرٌ كبير؛ ففي هذا بيانُ جزاءِ الفريقين؛ فاختر أن تكون من أهلِ الإيمانِ والعملِ لتنال المغفرةَ والأجرَ الكبير، لا من أهلِ الكفرِ والعذابِ الشديد، فالجزاءُ بحسبِ العمل، فاجتهد لتكون من أهلِ المغفرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اختيارُ الإيمانِ والعملِ لنيلِ المغفرةِ والأجرِ الكبير."},"action":{"text":"اختر لنفسك أن تكون من أهلِ الإيمانِ والعملِ الصالحِ الذين لهم مغفرةٌ وأجرٌ كبير، لا من أهلِ الكفرِ الذين لهم عذابٌ شديد «والذين آمنوا وعملوا الصالحات لهم مغفرة وأجر كبير»؛ فالجزاءُ بحسبِ العمل؛ فاجتهد في تحقيقِ الإيمانِ والإكثارِ من العملِ الصالح؛ فبهما تُنال المغفرةُ والأجرُ الكبير؛ واحذر الكفرَ والمعصيةَ الموصلين إلى العذابِ الشديد؛ فوازن بين الفريقين ومصيريهما: مغفرةٌ وأجرٌ كبيرٌ لأهلِ الإيمان، وعذابٌ شديدٌ لأهلِ الكفر؛ فاختر الطريقَ الموصلَ إلى المغفرة؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ فمن آمن وعمل صالحًا فاز، ومن كفر وعصى خسر؛ فاجعل غايتك المغفرةَ والأجرَ الكبير."}},{"n":8,"reflection":{"text":"«أفمن زين له سوء عمله فرآه حسنا فإن الله يضل من يشاء ويهدي من يشاء فلا تذهب نفسك عليهم حسرات إن الله عليم بما يصنعون» — أفمن زُيِّن له سوءُ عمله فرآه حسنًا (كمن هداه الله)؟ فإنّ الله يضلّ من يشاء ويهدي من يشاء، فلا تُهلك نفسك حسرةً على المعرضين، إنّ الله عليمٌ بما يصنعون؛ ففي هذا خطرُ تزيينِ السوء، والنهيُ عن الحزنِ المهلكِ على المعرضين؛ فاحذر أن يُزيَّن لك سوءُ عملك فتحسبه حسنًا، فاعرض أعمالك على الشرع، ولا تُهلك نفسك حزنًا على من أعرض، فالهدايةُ بيدِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تزيينِ السوء، وعدمُ الحزنِ المهلكِ على المعرضين."},"action":{"text":"احذر أن يُزيَّن لك سوءُ عملك فتراه حسنًا فتتمادى فيه وأنت تحسب أنك تحسن، فذلك من أعظمِ الخطر «أفمن زين له سوء عمله فرآه حسنا»؛ فاعرض أعمالك على ميزانِ الشرعِ لا على استحسانِ نفسك؛ وراقب الله في عملك؛ ولا تُهلك نفسك حزنًا وحسرةً على من أعرض عن الحقِّ بعد بلاغك «فلا تذهب نفسك عليهم حسرات»؛ فالهدايةُ بيدِ الله يضلّ من يشاء ويهدي من يشاء بحكمته وعدله؛ فليس عليك إلا البلاغ؛ فأدِّ ما عليك، وكِل أمرهم إلى الله العليمِ بما يصنعون؛ فلا تحمل همًّا لا يلزمك؛ فاجمع بين مراقبةِ عملك خشيةَ التزيين، وعدمِ الحزنِ المهلكِ على المعرضين؛ فبهذا تسلم من فخّ التزيين، ومن حرقةِ الحسرةِ على من لا تملك هدايته."}},{"n":9,"reflection":{"text":"«والله الذي أرسل الرياح فتثير سحابا فسقناه إلى بلد ميت فأحيينا به الأرض بعد موتها كذلك النشور» — والله الذي أرسل الرياحَ فتحرّك السحابَ فسقناه إلى بلدٍ ميّتٍ فأحيينا به الأرضَ بعد موتها، كذلك يكون البعثُ والنشور؛ ففي هذا الاستدلالُ بإحياءِ الأرضِ على البعث؛ فتأمّل إحياءَ الله للأرضِ الميتةِ بالمطر، لتوقن بالبعث، فمن أحيا الأرضَ الميتةَ قادرٌ على إحياءِ الموتى، فرسّخ يقينك بالنشورِ بالنظرِ في آياتِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستدلالُ بإحياءِ الأرضِ على قدرةِ الله على البعث."},"action":{"text":"تأمّل كيف يرسل الله الرياحَ فتثير السحابَ فيسوقه إلى بلدٍ ميّتٍ فيحيي به الأرضَ بعد موتها فتخضرّ وتنبت؛ فذلك برهانٌ على قدرته على إحياءِ الموتى وبعثهم «كذلك النشور»؛ فمن أحيا الأرضَ الهامدةَ قادرٌ على أن يبعثك بعد موتك؛ فرسّخ يقينك بالبعثِ والنشورِ بالنظرِ في هذه الآيةِ المتجدّدةِ أمامك كلَّ عام؛ فكلّما رأيت أرضًا ميتةً أحياها المطرُ فتذكّر بعثك؛ فاجعل التأمّلَ في آثارِ رحمةِ الله زادًا ليقينك بالبعثِ والقدرة؛ فمن أيقن بالبعثِ استعدَّ له بالعملِ الصالح؛ فالكونُ شاهدٌ على البعثِ لمن نظر واعتبر؛ فاجعل نظرك في إحياءِ الأرضِ نظرَ إيمانٍ يزيدك يقينًا بالنشور."}},{"n":10,"reflection":{"text":"«من كان يريد العزة فلله العزة جميعا إليه يصعد الكلم الطيب والعمل الصالح يرفعه والذين يمكرون السيئات لهم عذاب شديد ومكر أولئك هو يبور» — من كان يريد العزّةَ فليطلبها من الله، فلله العزّةُ جميعًا، إليه يصعد الكلامُ الطيّبُ (الذكرُ والتوحيد) والعملُ الصالحُ يرفعه، والذين يمكرون المكرَ السيّئ لهم عذابٌ شديد ومكرهم يهلك ويبطل؛ ففي هذا أنّ العزّةَ بيدِ الله تُنال بالإيمانِ والعملِ الصالح؛ فاطلب العزّةَ من الله بالكلمِ الطيّبِ والعملِ الصالح، لا بالمكرِ والباطل، فالعزّةُ في طاعةِ الله لا في معصيته، والمكرُ السيّئُ يبور.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العزّةِ من الله بالكلمِ الطيّبِ والعملِ الصالح."},"action":{"text":"اطلب العزّةَ والرفعةَ من الله وحده، فله العزّةُ جميعًا يؤتيها من يشاء «من كان يريد العزة فلله العزة جميعا»؛ فالعزّةُ تُنال بالإيمانِ والتوحيدِ والكلمِ الطيّبِ (الذكرِ والدعاءِ والقولِ الحسن) والعملِ الصالحِ الذي يرفعه الله؛ فاعمر لسانك بالذكرِ الطيّب، وجوارحك بالعملِ الصالح؛ فبهما ترتفع درجتك عند الله وتنال العزّة؛ واحذر طلبَ العزّةِ بالمكرِ السيّئِ والباطلِ والمعصية، فإنّ ذلك ذلٌّ وهلاك، ومكرُ الماكرين يبور ويبطل ويحيق بأهله «ومكر أولئك هو يبور»؛ فالعزّةُ الحقّةُ في طاعةِ الله، والذلُّ في معصيته؛ فمن طلب العزّةَ بطاعةِ الله نالها، ومن طلبها بالمكرِ والباطلِ ذلَّ وخسر؛ فاجعل عزّك في عبوديّتك لله، وكلمك طيّبًا، وعملك صالحًا؛ فبها تُرفَع وتُعزّ."}},{"n":11,"reflection":{"text":"«والله خلقكم من تراب ثم من نطفة ثم جعلكم أزواجا وما تحمل من أنثى ولا تضع إلا بعلمه وما يعمر من معمر ولا ينقص من عمره إلا في كتاب إن ذلك على الله يسير» — والله خلقكم من ترابٍ (بخلقِ آدم) ثم من نطفة، ثم جعلكم أزواجًا ذكورًا وإناثًا، وما تحمل أنثى ولا تضع إلا بعلمه، وما يُطال عمرُ أحدٍ ولا يُنقَص منه إلا وهو مكتوبٌ في كتاب، إنّ ذلك على الله يسير؛ ففي هذا تقريرُ إحاطةِ علمِ الله بالخلقِ والأعمار؛ فتأمّل أصلك وإحاطةَ علمِ الله بك، فمن أحاط علمه بحملِ كلِّ أنثى وعمرِ كلِّ نفسٍ فراقبه، واعلم أنّ أجلك مكتوبٌ، فاعمل قبل انقضائه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في إحاطةِ علمِ الله بالخلقِ والأعمار، والعملُ قبل الأجل."},"action":{"text":"تأمّل أصلك: خلقك الله من ترابٍ ثم من نطفةٍ ثم جعلكم أزواجًا؛ وتأمّل إحاطةَ علمِ الله بكلِّ شيء، فما تحمل أنثى ولا تضع إلا بعلمه، وما يُطال عمرُ معمَّرٍ ولا يُنقَص منه إلا وهو مكتوبٌ في كتاب «وما يعمر من معمر ولا ينقص من عمره إلا في كتاب»؛ فمن أحاط علمه بهذه الدقائقِ فراقبه في أعمالك؛ واعلم أنّ عمرك وأجلك محدّدٌ مكتوبٌ عند الله؛ فاعمل الصالحاتِ قبل انقضاءِ عمرك؛ ولا تسوّف بالطاعة؛ فالأجلُ مكتوبٌ لا يزيد ولا ينقص؛ فاغتنم عمرك في طاعةِ الله؛ فمن استحضر أنّ عمره محدودٌ وأنّ الله محيطٌ به بادر بالعمل؛ فالعمرُ رأسُ مالك، فاستثمره في الباقياتِ الصالحاتِ قبل أن ينقضي؛ فذلك على الله يسير، وعليك أن تستعدّ للأجلِ المكتوب."}},{"n":12,"reflection":{"text":"«وما يستوي البحران هذا عذب فرات سائغ شرابه وهذا ملح أجاج ومن كل تأكلون لحما طريا وتستخرجون حلية تلبسونها وترى الفلك فيه مواخر لتبتغوا من فضله ولعلكم تشكرون» — وما يستوي البحران: هذا عذبٌ شديدُ العذوبةِ سائغٌ شرابه، وهذا ملحٌ شديدُ الملوحة، ومن كلٍّ منهما تأكلون سمكًا طريًّا وتستخرجون حليةً (كاللؤلؤ) تلبسونها، وترى السفنَ تشقّ الماءَ لتطلبوا من فضلِ الله بالتجارة، ولعلّكم تشكرون؛ ففي هذا تعدادُ نعمِ الله في البحرين؛ فتأمّل نعمَ الله في البحرِ من الطعامِ والحليةِ والفلك، واشكره عليها، فمن سخّر لك البحرَ ونعمه يستحقّ شكرك، فاجعل النعمَ سبيلًا للشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في نعمِ الله في البحرِ وشكرُه عليها."},"action":{"text":"تأمّل نعمَ الله في البحرين العذبِ والملح، وكيف سخّرهما لك: تأكل من كلٍّ منهما لحمًا طريًّا (السمك)، وتستخرج منهما الحليةَ (كاللؤلؤ) تلبسها، وترى الفلكَ تشقّ الماءَ لتطلب فضلَ الله بالتجارةِ والأسفار «لتبتغوا من فضله ولعلكم تشكرون»؛ فاشكر الله على هذه النعمِ المتعدّدةِ في البحر؛ فالغايةُ من عرضِ هذه النعمِ أن تشكر؛ فقابل نعمَ الله بالحمدِ والطاعةِ لا بالكفرانِ والغفلة؛ فكلّما رأيت البحرَ أو أكلت من خيره أو ركبت الفلكَ فتذكّر منعمها واشكره؛ فمن تأمّل آياتِ الله في الكونِ وشكر نعمه زاده الله؛ فاجعل النعمَ المسخّرةَ لك وسيلةً لشكرِ المنعمِ وطاعته؛ فالشكرُ يستبقي النعمَ ويستجلب المزيد."}},{"n":13,"reflection":{"text":"«يولج الليل في النهار ويولج النهار في الليل وسخر الشمس والقمر كل يجري لأجل مسمى ذلكم الله ربكم له الملك والذين تدعون من دونه ما يملكون من قطمير» — يدخل الليلَ في النهارِ والنهارَ في الليل، وسخّر الشمسَ والقمرَ يجريان إلى أجلٍ محدّد، ذلكم الله ربّكم له الملكُ كلُّه، والذين تدعونهم من دونه ما يملكون من قطميرٍ (قشرةِ نواة)؛ ففي هذا تقريرُ تدبيرِ الله وملكِه وعجزِ ما سواه؛ فاعبد الله الذي له الملكُ كلُّه، ولا تدعُ من لا يملك قشرةَ نواة، فالملكُ لله وحده، وما سواه عاجزٌ لا يملك شيئًا، فأخلص العبادةَ للمالك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إفرادُ الله بالعبادةِ فله الملكُ، وما سواه لا يملك شيئًا."},"action":{"text":"أفرد الله بالعبادةِ والدعاء، فهو الذي يدبّر الكونَ: يولج الليلَ في النهارِ والنهارَ في الليل، وسخّر الشمسَ والقمرَ يجريان لأجلٍ مسمًّى، وله الملكُ كلُّه «ذلكم الله ربكم له الملك»؛ أما ما تدعونه من دونه فلا يملك من قطميرٍ (قشرةِ نواةٍ) شيئًا «ما يملكون من قطمير»؛ فكيف يُدعى من لا يملك شيئًا ويُترَك مالكُ كلِّ شيء؟ فاصرف عبادتك ودعاءك وتوكّلك إلى الله المالكِ المدبّرِ وحده؛ ولا تجعل له شريكًا عاجزًا لا يملك ذرّة؛ فمن دعا غيرَ الله فقد دعا من لا يملك له نفعًا ولا ضرًّا؛ فتأمّل تدبيرَ الله للكونِ وملكه المطلق؛ فيحملك ذلك على إفراده بالعبادة؛ فالملكُ كلُّه لله، والعبادةُ كلُّها له؛ فلا تعبد عاجزًا لا يملك قشرةَ نواة."}},{"n":14,"reflection":{"text":"«إن تدعوهم لا يسمعوا دعاءكم ولو سمعوا ما استجابوا لكم ويوم القيامة يكفرون بشرككم ولا ينبئك مثل خبير» — إن تدعوا هؤلاء الشركاءَ لا يسمعوا دعاءكم، ولو سمعوا ما استجابوا لكم، ويومَ القيامةِ يتبرّؤون من شرككم بهم، ولا يخبرك بالحقيقةِ مثلُ الله الخبير؛ ففي هذا بيانُ عجزِ المعبوداتِ التام؛ فلا تدعُ من لا يسمع ولا يستجيب ويتبرّأ منك، بل ادعُ الله الخبيرَ السميعَ المجيب، فالمعبوداتُ من دونِ الله عاجزةٌ لا تنفع، والدعاءُ حقٌّ لله وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الخبير"],"heart_state":{"text":"إفرادُ الله بالدعاءِ لعجزِ ما سواه عن السمعِ والإجابة."},"action":{"text":"أفرد الله بالدعاء، ولا تدعُ من دونه من المعبوداتِ الباطلة، فإنها لا تسمع دعاءك، ولو سمعت لم تستجب لك، وهي تتبرّأ منك يومَ القيامة «إن تدعوهم لا يسمعوا دعاءكم ولو سمعوا ما استجابوا لكم ويوم القيامة يكفرون بشرككم»؛ فكيف تدعو من لا يسمع ولا يستجيب ويخذلك يومَ الحاجة؟ فاصرف دعاءك ورجاءك إلى الله السميعِ المجيبِ الخبيرِ بحالك؛ فهو الذي يسمع دعاءك ويستجيب لك؛ ولا يخبرك بحقيقةِ عجزِ المعبوداتِ مثلُ الله الخبير «ولا ينبئك مثل خبير»؛ فحقّق التوحيدَ الخالص؛ واجعل دعاءك ورجاءك وتوكّلك لله وحده؛ فمن دعا الله أجابه، ومن دعا غيره خُذِل وتبرّأ منه معبوده؛ فلا تعلّق قلبك بعاجزٍ لا يسمع ولا ينفع؛ بل بالسميعِ المجيبِ الخبير."}}]},{"title":"فقرُ الناسِ إلى الله، والمسؤوليةُ الفردية، وتفاوتُ الناس","range":[15,22],"theme":"أنّ الناسَ فقراءُ إلى الله وهو الغنيُّ الحميد، وقدرتُه على إذهابهم والإتيانِ بغيرهم، والمسؤوليةُ الفرديةُ وأنّ المنتفعَ أهلُ الخشية، وسلسلةُ عدمِ الاستواء: الأعمى والبصير، والظلماتُ والنور، والظلُّ والحرور، والأحياءُ والأموات","verses":[{"n":15,"reflection":{"text":"«يا أيها الناس أنتم الفقراء إلى الله والله هو الغني الحميد» — يا أيها الناسُ أنتم المحتاجون الفقراءُ إلى الله في كلِّ شؤونكم، والله هو الغنيُّ عنكم الحميدُ في ذاته وأفعاله؛ ففي هذا تقريرُ فقرِ العبدِ وغنى الله؛ فاستشعر فقرك الدائمَ إلى الله، فأنت محتاجٌ إليه في كلِّ نفَس، وهو غنيٌّ عنك، فتذلّل له وافتقر إليه، فالعبدُ فقيرٌ إلى الله في كلِّ حال، والافتقارُ إليه عين الغنى.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الغني","الحميد"],"heart_state":{"text":"استشعارُ الفقرِ الدائمِ إلى الله، والتذلّلُ له."},"action":{"text":"استشعر فقرك الدائمَ إلى الله في كلِّ شؤونك: في وجودك وبقائك ورزقك وصحّتك وهدايتك وكلِّ نفَسٍ تتنفّسه، فأنت الفقيرُ المحتاجُ إليه، وهو الغنيُّ عنك الحميدُ في ذاته «يا أيها الناس أنتم الفقراء إلى الله والله هو الغني الحميد»؛ فتذلّل لله وافتقر إليه واطرح حاجتك بين يديه؛ فمن عرف فقره إلى الله لجأ إليه في كلِّ أمر، وتذلّل له، ولم يستغنِ عنه لحظة؛ فالافتقارُ إلى الله عين الغنى، والاستغناءُ عنه عين الفقر؛ فاجعل قلبك دائمَ الافتقارِ إلى الله، معترفًا بحاجتك إليه؛ فهو الغنيُّ الذي لا يحتاج إليك، وأنت الفقيرُ الذي لا غنى لك عنه طرفةَ عين؛ فالزم بابه، وتذلّل له، واطلب منه كلَّ حاجاتك؛ فمن افتقر إلى الله أغناه."}},{"n":16,"reflection":{"text":"«إن يشأ يذهبكم ويأت بخلق جديد» — إن يشأ الله يُذهبكم ويأتِ بخلقٍ جديدٍ غيركم أطوعَ منكم؛ ففي هذا تقريرُ قدرةِ الله وغناه عن الخلق؛ فاعلم أنّ الله غنيٌّ عنك قادرٌ على إذهابك والإتيانِ بغيرك، فلا تغترَّ بنفسك، وتواضع لله، فبقاؤك نعمةٌ منه، وطاعتك لنفعك لا لحاجته إليك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ لله الغنيِّ القادرِ على إذهابِ الخلقِ والإتيانِ بغيرهم."},"action":{"text":"تواضع لله واعرف قدره، فإنه غنيٌّ عنك قادرٌ على أن يُذهبك ويأتيَ بخلقٍ جديدٍ غيرك أطوعَ منك «إن يشأ يذهبكم ويأت بخلق جديد»؛ فلا تغترَّ بنفسك أو بطاعتك، ولا تمنن على الله بعبادتك؛ فالله غنيٌّ عنك وعن عبادتك؛ وإنما بقاؤك في الأرضِ نعمةٌ منه وإمهال؛ وطاعتك تعود لنفعك لا لحاجةِ الله إليها؛ فاستشعر ضعفك وحاجتك، وغنى الله وقدرته؛ فمن عرف أنّ الله غنيٌّ عنه قادرٌ على استبداله تواضع وذلَّ لربّه؛ فاشكر الله على نعمةِ الإمهالِ والبقاء، واستعملها في طاعته؛ ولا تغترَّ بقوّةٍ أو مكانةٍ فالله قادرٌ على إذهابك في لحظة؛ فالتواضعُ لله والافتقارُ إليه سبيلُ العزّةِ والقرب."}},{"n":17,"reflection":{"text":"«وما ذلك على الله بعزيز» — وما ذلك الإذهابُ والإتيانُ بخلقٍ جديدٍ على الله بممتنعٍ ولا صعب، بل هو يسيرٌ عليه؛ ففي هذا تقريرُ سهولةِ ذلك على الله؛ فأيقن بأنّ الله على كلِّ شيءٍ قدير، لا يعجزه شيء، فما يشاؤه يفعله بلا صعوبة، فسلّم لقدرته، ولا تستبعد شيئًا من قدرته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ كلَّ شيءٍ يسيرٌ على الله لا يعجزه."},"action":{"text":"أيقن بأنّ إذهابَ الخلقِ والإتيانَ بغيرهم، وكلَّ ما يشاؤه الله، يسيرٌ عليه لا صعوبةَ فيه ولا امتناع «وما ذلك على الله بعزيز»؛ فالله على كلِّ شيءٍ قدير، لا يعجزه شيءٌ في الأرضِ ولا في السماء؛ فسلّم لقدرته المطلقة، ولا تستبعد شيئًا من قدرته سبحانه؛ فما شاءه كان بلا مؤونةٍ ولا مشقّة، وما لم يشأه لم يكن؛ فمن أيقن بكمالِ قدرةِ الله وثق به وتوكّل عليه، ولم يستبعد نصره ولا فرجه ولا بعثه للموتى؛ فاطلب حاجتك من القادرِ الذي لا يعجزه شيء؛ فما استعصى على غيره فهو على الله يسير؛ فاجعل يقينك بقدرةِ الله راسخًا؛ فبه يقوى توكّلك ويطمئنّ قلبك؛ فلا شيءَ يعجز الله، وكلُّ شيءٍ عليه هيّن."}},{"n":18,"reflection":{"text":"«ولا تزر وازرة وزر أخرى وإن تدع مثقلة إلى حملها لا يحمل منه شيء ولو كان ذا قربى إنما تنذر الذين يخشون ربهم بالغيب وأقاموا الصلاة ومن تزكى فإنما يتزكى لنفسه وإلى الله المصير» — ولا تحمل نفسٌ آثمةٌ إثمَ نفسٍ أخرى، وإن تدعُ نفسٌ مثقلةٌ بالذنوبِ من يحمل عنها شيئًا لم يُحمَل عنها شيءٌ ولو كان قريبًا، إنما ينتفع بإنذارك الذين يخشون ربّهم بالغيبِ وأقاموا الصلاة، ومن تطهّر من الذنوبِ فإنما يتطهّر لنفسه، وإلى الله المصير؛ ففي هذا تقريرُ المسؤوليةِ الفردية، وأنّ المنتفعَ بالإنذارِ أهلُ الخشية؛ فاحمل وزرك بنفسك، ولا تتّكل على أحد، وتزكَّ لنفسك، فالنجاةُ بعملك أنت، ولا يحمل أحدٌ عنك ذنبك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المسؤوليةُ الفردية، والتزكّي للنفس، وأنّ المنتفعَ أهلُ الخشية."},"action":{"text":"اعلم أنّ كلَّ نفسٍ تحمل وزرها وحدها، لا تحمل وزرَ غيرها ولا يحمل غيرُها وزرها، ولو كان أقربَ قريب «ولا تزر وازرة وزر أخرى... ولو كان ذا قربى»؛ فاحمل مسؤوليةَ عملك بنفسك، ولا تتّكل على أحدٍ في نجاتك؛ وتزكَّ (تطهّر من الذنوبِ بالتوبةِ والعمل) فإنما تتزكّى لنفسك «ومن تزكى فإنما يتزكى لنفسه»؛ واعلم أنّ المنتفعَ بالإنذارِ والموعظةِ هو من يخشى ربّه بالغيبِ ويقيم الصلاة؛ فكن منهم؛ فاجعل خشيةَ الله في قلبك، وأقم صلاتك، وتزكَّ لنفسك؛ فالنجاةُ بعملك أنت لا بأحدٍ سواك؛ وإلى الله المصير؛ فاعمل لآخرتك عملَ من يعلم أنه محاسَبٌ وحده؛ فمن أصلح نفسه نجا، ومن اتّكل على غيره خاب."}},{"n":19,"reflection":{"text":"«وما يستوي الأعمى والبصير» — وما يستوي الأعمى (الكافرُ الجاهل) والبصيرُ (المؤمنُ العالم)؛ ففي هذا تقريرُ عدمِ استواءِ المؤمنِ والكافر؛ فاعلم أنّ المؤمنَ البصيرَ بالحقِّ لا يستوي مع الكافرِ الأعمى عنه، فاطلب بصيرةَ الإيمانِ والعلم، ولا تكن أعمى عن الحقّ، فشتّانَ بين من أبصر الحقَّ ومن عمي عنه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ بصيرةِ الإيمانِ والعلم، فلا يستوي البصيرُ والأعمى."},"action":{"text":"اعلم أنّ المؤمنَ البصيرَ بالحقِّ العالمَ به لا يستوي مع الكافرِ الأعمى عنه الجاهلِ به «وما يستوي الأعمى والبصير»؛ فاطلب بصيرةَ الإيمانِ والعلمِ التي تُبصر بها الحقَّ فتتّبعه والباطلَ فتجتنبه؛ ولا تكن أعمى القلبِ عن الحقّ؛ فشتّانَ بين من أبصر طريقه إلى الله فسلكه، ومن عمي عنه فتاه؛ فاجتهد في تحصيلِ العلمِ النافعِ والإيمانِ الصادقِ الذي يورث البصيرة؛ فبها تفرّق بين الحقِّ والباطل، والهدى والضلال؛ فمن رزقه الله بصيرةَ الإيمانِ والعلمِ فقد رزقه خيرًا كثيرًا؛ فاطلب من الله أن يريك الحقَّ حقًّا ويرزقك اتّباعه، والباطلَ باطلًا ويرزقك اجتنابه؛ فالبصيرةُ نعمةٌ، والعمى عن الحقِّ مصيبة؛ فكن من أهلِ البصائر."}},{"n":20,"reflection":{"text":"«ولا الظلمات ولا النور» — ولا تستوي الظلماتُ (الكفرُ والجهلُ والمعصية) والنورُ (الإيمانُ والعلمُ والطاعة)؛ ففي هذا تقريرُ عدمِ استواءِ الكفرِ والإيمان؛ فاطلب نورَ الإيمانِ واجتنب ظلماتِ الكفرِ والمعصية، فشتّانَ بين من هو في نورِ الهدى ومن هو في ظلماتِ الضلال، فاسلك سبيلَ النور.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ نورِ الإيمانِ واجتنابُ ظلماتِ الكفرِ والمعصية."},"action":{"text":"اعلم أنّ ظلماتِ الكفرِ والجهلِ والمعصيةِ لا تستوي مع نورِ الإيمانِ والعلمِ والطاعة «ولا الظلمات ولا النور»؛ فاطلب نورَ الإيمانِ والهدى والعملِ الصالح، واجتنب ظلماتِ الكفرِ والضلالِ والمعصية؛ فشتّانَ بين من يمشي في نورِ الهدى ومن يتخبّط في ظلماتِ الضلال؛ فاسلك سبيلَ النور: بالإيمانِ والعلمِ والطاعةِ وتلاوةِ القرآنِ وذكرِ الله؛ فبها يستنير قلبك وطريقك؛ واحذر أسبابَ الظلمة: من الكفرِ والجهلِ والمعاصي والغفلة؛ فمن أقبل على الله استنار قلبه، ومن أعرض عنه أظلم؛ فاطلب من الله أن يجعل في قلبك نورًا وفي بصرك نورًا وفي سمعك نورًا؛ فالنورُ حياةٌ وهدًى، والظلمةُ موتٌ وضلال؛ فكن من أهلِ النور، الساعين إليه، الهاربين من الظلمات."}},{"n":21,"reflection":{"text":"«ولا الظل ولا الحرور» — ولا يستوي الظلُّ (نعيمُ المؤمنين أو الراحة) والحرورُ (حرُّ النارِ أو عذابُ الكافرين)؛ ففي هذا تقريرُ عدمِ استواءِ الجزاءين؛ فاعمل لتكون من أهلِ الظلِّ والراحةِ لا من أهلِ الحرِّ والعذاب، فشتّانَ بين جزاءِ المؤمنِ وجزاءِ الكافر، فاختر ما يوصلك إلى ظلِّ رحمةِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ ظلِّ الرحمة، فلا يستوي الظلُّ والحرور."},"action":{"text":"اعلم أنّ الظلَّ (وهو الراحةُ ونعيمُ المؤمنين) لا يستوي مع الحرورِ (وهو حرُّ العذابِ ومصيرُ الكافرين) «ولا الظل ولا الحرور»؛ فاعمل الصالحاتِ لتكون من أهلِ الظلِّ والراحةِ والنعيم، لا من أهلِ الحرِّ والعذابِ والشقاء؛ فشتّانَ بين جزاءِ المؤمنِ الطائعِ وجزاءِ الكافرِ العاصي؛ فاختر لنفسك الطريقَ الموصلَ إلى ظلِّ رحمةِ الله ونعيمِ جنّته؛ واجتنب الطريقَ الموصلَ إلى حرِّ نقمته وعذابِ ناره؛ فالعبرةُ بالعمل؛ فمن عمل للظلِّ أظلّه الله، ومن عمل لأسبابِ الحرِّ أحرقه؛ فبادر بالأعمالِ الصالحةِ التي تظلّك يومَ لا ظلَّ إلا ظلُّ الله؛ فاجعل غايتك النعيمَ والراحةَ في جوارِ الله؛ فالعاقلُ من عمل لما ينجّيه من الحرِّ ويبلّغه الظلّ."}},{"n":22,"reflection":{"text":"«وما يستوي الأحياء ولا الأموات إن الله يسمع من يشاء وما أنت بمسمع من في القبور» — وما يستوي الأحياءُ (المؤمنون أحياءُ القلوب) والأمواتُ (الكفارُ موتى القلوب)، إنّ الله يُسمِع من يشاء إسماعَ هداية، وما أنت بمُسمِعٍ من في القبورِ (الكفارِ الذين ماتت قلوبهم)؛ ففي هذا أنّ هدايةَ القلوبِ بيدِ الله؛ فاعلم أنّ المؤمنَ الحيَّ القلبِ لا يستوي مع الكافرِ الميّتِ القلب، فاحرص على حياةِ قلبك بالإيمان، ولا تحزن على من مات قلبه، فالهدايةُ بيدِ الله لا بيدك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["السميع"],"heart_state":{"text":"الحرصُ على حياةِ القلبِ بالإيمان، وأنّ الهدايةَ بيدِ الله."},"action":{"text":"اعلم أنّ المؤمنَ الحيَّ القلبِ بالإيمانِ والعلمِ لا يستوي مع الكافرِ الميّتِ القلبِ بالكفرِ والجهل «وما يستوي الأحياء ولا الأموات»؛ فاحرص على حياةِ قلبك بالإيمانِ والذكرِ والعلمِ والطاعة؛ فالقلبُ يحيا بالإيمانِ ويموت بالكفرِ والغفلة؛ واعلم أنّ الله يُسمِع من يشاء إسماعَ هدايةٍ وقبول، وأنك لست بمُسمِعٍ من مات قلبه كأهلِ القبور «وما أنت بمسمع من في القبور»؛ فهدايةُ القلوبِ بيدِ الله لا بيدك؛ فأدِّ ما عليك من البلاغِ والنصح، ولا تحزن حزنًا يهلكك على من مات قلبه فأعرض عن الحق؛ فليس عليك إلا البلاغ؛ فادعُ وأحسن، وأحيِ قلبك أنت أوّلًا بالإيمان؛ فمن أحيا الله قلبه سمع الحقَّ فاتّبعه، ومن أماته أعرض عنه؛ فاطلب من الله حياةَ قلبك وثباته."}}]},{"title":"النذارةُ العامّة، وآياتُ الألوان، وخشيةُ العلماء، وتجارةُ المؤمنين","range":[23,30],"theme":"أنّ النبيَّ نذيرٌ أُرسِل بالحقّ وما من أمّةٍ إلا خلا فيها نذير، وتسليتُه في التكذيب، والتأمّلُ في تنوّعِ الثمارِ والجبالِ والألوان، وأنّ الخشيةَ ثمرةُ العلم، وتجارةُ التلاوةِ والصلاةِ والإنفاقِ التي لن تبور","verses":[{"n":23,"reflection":{"text":"«إن أنت إلا نذير» — ما أنت يا محمدُ إلا نذيرٌ تبلّغ وتحذّر، لا مسيطرٌ على القلوب؛ ففي هذا حصرُ مهمّةِ النبيِّ في الإنذار؛ فأدِّ ما عليك من الإنذارِ والنصح، ولا تحمل همَّ ما ليس إليك، فمهمّةُ الرسولِ البلاغُ والإنذار، والهدايةُ بيدِ الله، فبلّغ واحتسب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ الإنذارِ والنصح، وعدمُ حملِ همِّ ما ليس إليك."},"action":{"text":"أدِّ ما عليك من الإنذارِ والنصحِ والبلاغ، ولا تحمل همَّ ما ليس إليك من هدايةِ القلوب، فإنّ مهمّةَ الرسولِ الإنذارُ والبلاغُ لا السيطرةُ على القلوب «إن أنت إلا نذير»؛ فبلّغ الحقَّ وحذّر من الباطلِ بحكمة، ثم كِل أمرَ القبولِ إلى الله؛ فليس عليك إلا البلاغ؛ فلا تُتعب نفسك حسرةً على من أعرض؛ فادعُ وأنذر وأحسن، محتسبًا أجرك على الله؛ فمن أدّى ما عليه من الإنذارِ برئت ذمّته؛ فاجعل همّك أداءَ الأمانةِ لا ضمانَ النتيجة؛ فالنتيجةُ بيدِ الله، والبلاغُ عليك؛ فبلّغ وأنذر، وامضِ في طريقك محتسبًا، غيرَ حاملٍ ما لا يلزمك."}},{"n":24,"reflection":{"text":"«إنا أرسلناك بالحق بشيرا ونذيرا وإن من أمة إلا خلا فيها نذير» — إنا أرسلناك بالحقِّ بشيرًا للمؤمنين ونذيرًا للكافرين، وما من أمّةٍ إلا مضى فيها نذيرٌ يدعوها إلى الله؛ ففي هذا عدلُ الله في إرسالِ النذرِ لكلِّ أمّة؛ فاعلم أنّ الله لم يترك أمّةً بلا نذير، عدلًا منه وإقامةً للحجّة، فاحمد الله أن بلغتك النذارة، واتّبع النذيرَ، فلا حجّةَ لمن أُنذِر فأعرض.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحمدُ لله على النذارة، واتّباعُ النذيرِ فلا حجّةَ بعده."},"action":{"text":"اعلم أنّ الله بعدله لم يترك أمّةً من الأممِ بلا نذيرٍ يدعوها إلى الحقّ ويقيم عليها الحجّة «وإن من أمة إلا خلا فيها نذير»؛ فاحمد الله أن بلغتك النذارةُ على يدِ خاتمِ الأنبياءِ محمدٍ ﷺ الذي أُرسِل بالحقِّ بشيرًا ونذيرًا؛ واتّبع هذا النذيرَ، واعمل بما جاء به؛ فلا حجّةَ لمن أُنذِر فأعرض؛ فقد أقام الله الحجّةَ بإرسالِ الرسل؛ فبادر بالاستجابةِ للنذارة، ولا تعتذر بعد قيامِ الحجّة؛ فمن اتّبع النذيرَ نال بشارته، ومن أعرض عنه لحقته نذارته؛ فاجعل نعمةَ بلوغِ النذارةِ إليك سببًا للشكرِ والاتّباع، لا للإعراضِ والتكذيب؛ فالبشارةُ لمن آمن، والنذارةُ لمن كفر؛ فكن من أهلِ البشارة."}},{"n":25,"reflection":{"text":"«وإن يكذبوك فقد كذب الذين من قبلهم جاءتهم رسلهم بالبينات وبالزبر وبالكتاب المنير» — وإن يكذّبك قومك فقد كذّب الذين من قبلهم رسلهم، جاءتهم رسلهم بالمعجزاتِ الواضحةِ والصحفِ والكتابِ المنير؛ ففي هذا تسليةُ النبيِّ وأنّ التكذيبَ سنّةٌ قديمة؛ فلا يحزنك تكذيبُ المكذّبين، فقد كُذِّب الرسلُ قبلك مع ما جاؤوا به من البيّناتِ والكتب، فاصبر كما صبروا، فالتكذيبُ سنّةُ الأممِ مع الرسل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على التكذيب، فهو سنّةُ الأممِ مع الرسل."},"action":{"text":"لا يحزنك ولا يوهنك تكذيبُ المكذّبين لك أو لدعوتك، فإنّ ذلك سنّةٌ قديمةٌ في الأممِ مع رسلها، فقد كُذِّب الذين من قبلهم مع ما جاءتهم به رسلهم من البيّناتِ الواضحةِ والصحفِ والكتابِ المنير «جاءتهم رسلهم بالبينات وبالزبر وبالكتاب المنير»؛ فاصبر كما صبر الرسلُ من قبلك على تكذيبِ أقوامهم؛ فالتكذيبُ لا يقدح في الحقّ، ولا يدلّ على بطلانِ الدعوة؛ فامضِ في دعوتك محتسبًا صابرًا؛ ولا تحمل همَّ من كذّب أو أعرض؛ فليس عليك إلا البلاغ؛ فالعاقبةُ للمرسلين وأتباعهم؛ فاجعل عزاءك أنّ من قبلك من الرسلِ لقوا مثلَ ما لقيت فصبروا فنصرهم الله؛ فالصبرُ على التكذيبِ سبيلُ النصرِ والعاقبةِ الحسنة."}},{"n":26,"reflection":{"text":"«ثم أخذت الذين كفروا فكيف كان نكير» — ثم أخذتُ الذين كفروا وكذّبوا الرسلَ بالعقوبةِ والهلاك، فكيف كان إنكاري عليهم وعقوبتي لهم؟ ففي هذا التخويفُ بعاقبةِ المكذّبين؛ فاعتبر بعاقبةِ المكذّبين الذين أخذهم الله، فكيف كان نكيرُه بهم؟ فاحذر التكذيبَ فعاقبتُه العقوبةُ الشديدة، والزم التصديقَ والاتّباعَ لتنجو.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ المكذّبين والحذرُ من التكذيب."},"action":{"text":"اعتبر بعاقبةِ الذين كفروا وكذّبوا الرسلَ من الأممِ السابقة، كيف أخذهم الله بالعقوبةِ والهلاكِ والنكال «ثم أخذت الذين كفروا فكيف كان نكير»؛ فتأمّل شدّةَ إنكارِ الله عليهم وعقوبته لهم؛ فاحذر التكذيبَ بالحقِّ والرسل، فإنّ عاقبتَه العقوبةُ الشديدة؛ والزم التصديقَ بالحقِّ واتّباعَ الرسولِ ﷺ لتنجو من عاقبةِ المكذّبين؛ فاجعل من مصارعِ الأممِ الهالكةِ عبرةً تزيدك تصديقًا بالحقِّ وحذرًا من التكذيب؛ فالعاقبةُ للمصدّقين المتّبعين، والدمارُ للمكذّبين المعاندين؛ فبادر بالإيمانِ والاتّباعِ والطاعة؛ ولا تسلك سبيلَ من أخذهم الله بكفرهم؛ فالتصديقُ والاتّباعُ نجاة، والتكذيبُ والإعراضُ هلاك."}},{"n":27,"reflection":{"text":"«ألم تر أن الله أنزل من السماء ماء فأخرجنا به ثمرات مختلفا ألوانها ومن الجبال جدد بيض وحمر مختلف ألوانها وغرابيب سود» — ألم تر أنّ الله أنزل من السماءِ ماءً فأخرجنا به ثمراتٍ مختلفةً ألوانها، ومن الجبالِ طرائقُ بيضٌ وحمرٌ مختلفةُ الألوانِ وسودٌ شديدةُ السواد؟ ففي هذا التأمّلُ في تنوّعِ الثمارِ والجبالِ آيةً على قدرةِ الله؛ فتأمّل تنوّعَ ألوانِ الثمارِ والجبالِ من ماءٍ واحدٍ وأرضٍ واحدة، لتعظّم قدرةَ الله وحكمته، فمن نظر في هذا التنوّعِ البديعِ عرف عظمةَ الخالق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في تنوّعِ الخلقِ آيةً على قدرةِ الله وحكمته."},"action":{"text":"تأمّل كيف ينزّل الله الماءَ من السماء، فيخرج به ثماراتٍ مختلفةً ألوانها وطعومها، مع أنّ الماءَ واحدٌ والأرضَ واحدة؛ وتأمّل الجبالَ وفيها طرائقُ بيضٌ وحمرٌ وسودٌ مختلفةُ الألوان «فأخرجنا به ثمرات مختلفا ألوانها»؛ فهذا التنوّعُ البديعُ آيةٌ على قدرةِ الله وحكمته وعظمته؛ فاجعل نظرك في تنوّعِ خلقِ الله نظرَ تدبّرٍ يزيدك إيمانًا وتعظيمًا؛ فكلّما رأيت ثمرةً أو جبلًا مختلفَ الألوانِ فتذكّر عظمةَ خالقه الذي أبدع هذا التنوّع؛ فمن تأمّل بديعَ صنعِ الله في الكونِ ازداد يقينًا بقدرته وحكمته؛ فالكونُ كتابٌ مفتوحٌ يدلّ على الله؛ فاقرأ آياته بعينِ الاعتبار؛ فالتنوّعُ في الخلقِ من أعظمِ الدلائلِ على قدرةِ الله وإرادته وعلمه."}},{"n":28,"reflection":{"text":"«ومن الناس والدواب والأنعام مختلف ألوانه كذلك إنما يخشى الله من عباده العلماء إن الله عزيز غفور» — ومن الناسِ والدوابِّ والأنعامِ مختلفٌ ألوانه كذلك، إنما يخشى الله حقَّ خشيته من عباده العلماءُ الذين عرفوه، إنّ الله عزيزٌ غفور؛ ففي هذا أنّ الخشيةَ الحقّةَ ثمرةُ العلمِ بالله؛ فاطلب العلمَ الذي يورث خشيةَ الله، فأخشى الناسِ لله أعلمُهم به، فالعلمُ النافعُ ما أثمر خشيةً وعملًا، فكلّما ازددت علمًا بالله ازددت خشيةً له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العلمِ الذي يورث خشيةَ الله، فأخشاهم أعلمُهم به."},"action":{"text":"اطلب العلمَ النافعَ الذي يورث خشيةَ الله؛ فإنّ أخشى الناسِ لله وأعظمهم تعظيمًا له هم العلماءُ الذين عرفوه بأسمائه وصفاته وأفعاله «إنما يخشى الله من عباده العلماء»؛ فالخشيةُ الحقّةُ ثمرةُ العلمِ بالله؛ فكلّما ازددت علمًا بالله وبعظمته وقدرته وأسمائه وصفاته ازددت خشيةً له وتعظيمًا؛ فالعلمُ النافعُ ما أثمر خشيةً وعملًا وتقوى، لا مجرّدَ معلوماتٍ في الذهن؛ فاجعل غايةَ علمك أن يقودك إلى خشيةِ الله وطاعته؛ فمن علم عن الله خشيه، ومن جهله اجترأ عليه؛ فاطلب العلمَ الذي يخشّعك ويقرّبك من الله؛ فالله عزيزٌ (يُخشى لعزّته) غفورٌ (يُرجى لمغفرته)؛ فاجمع في قلبك خشيته ورجاءه؛ فالخشيةُ الممدوحةُ ما اقترنت بالعلمِ والعمل."}},{"n":29,"reflection":{"text":"«إن الذين يتلون كتاب الله وأقاموا الصلاة وأنفقوا مما رزقناهم سرا وعلانية يرجون تجارة لن تبور» — إنّ الذين يتلون كتابَ الله ويعملون به، وأقاموا الصلاة، وأنفقوا ممّا رزقناهم سرًّا وعلانيةً، يرجون تجارةً مع الله لن تكسد ولن تهلك؛ ففي هذا مدحُ أهلِ التلاوةِ والصلاةِ والإنفاق؛ فاتلُ كتابَ الله، وأقم الصلاة، وأنفق في الخيرِ سرًّا وعلانية، فهذه تجارةٌ رابحةٌ مع الله لن تبور، فاعمل بها لتربح.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التلاوةُ والصلاةُ والإنفاقُ تجارةٌ رابحةٌ مع الله لن تبور."},"action":{"text":"اتلُ كتابَ الله متدبّرًا عاملًا به، وأقم الصلاةَ بأركانها وخشوعها، وأنفق ممّا رزقك الله في وجوهِ الخيرِ سرًّا وعلانيةً؛ فهذه أعمالٌ يرجو أصحابها تجارةً رابحةً مع الله لن تكسد ولن تهلك «يرجون تجارة لن تبور»؛ فاجعل هذه الأعمالَ الثلاثةَ رأسَ مالك في التجارةِ مع الله: تلاوةَ القرآن، وإقامةَ الصلاة، والإنفاقَ في الخير؛ فبها تربح ربحًا لا خسارةَ فيه؛ فالتجارةُ مع الله رابحةٌ دائمًا؛ فمن قدّم لله عملًا صالحًا ربح أضعافه؛ فاعمر وقتك بتلاوةِ القرآن، وحافظ على صلاتك، وابذل من مالك في الخير؛ فبهذه التجارةِ الرابحةِ تنال أجرك موفًّى وزيادةً من فضلِ الله؛ فالباقياتُ الصالحاتُ خيرٌ عند ربّك ثوابًا وخيرٌ أملًا."}},{"n":30,"reflection":{"text":"«ليوفيهم أجورهم ويزيدهم من فضله إنه غفور شكور» — ليوفّيَ الله أهلَ التلاوةِ والصلاةِ والإنفاقِ أجورهم كاملةً ويزيدهم من فضله، إنه غفورٌ لذنوبهم شكورٌ لأعمالهم؛ ففي هذا وعدُ الله بتوفيةِ الأجرِ والزيادةِ من فضله؛ فاعمل صالحًا واثقًا بأنّ الله يوفّيك أجرك ويزيدك من فضله، فهو غفورٌ يغفر الزلل، شكورٌ يجزي على القليلِ الكثير، فأحسن العملَ راجيًا فضله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الشكور"],"heart_state":{"text":"العملُ برجاءِ توفيةِ الأجرِ والزيادةِ من فضلِ الغفورِ الشكور."},"action":{"text":"اعمل الصالحاتِ واثقًا بأنّ الله يوفّيك أجرك كاملًا غيرَ منقوص، ويزيدك من فضله وكرمه «ليوفيهم أجورهم ويزيدهم من فضله»؛ فهو الغفورُ الذي يغفر زلّاتك وتقصيرك، الشكورُ الذي يجزي على العملِ القليلِ الأجرَ الكثير، ويقبل اليسيرَ ويثيب عليه الجزيل؛ فأحسن العملَ راجيًا فضلَ الله لا مقتصرًا على عملك؛ فالله يقابل حسناتك بالمضاعفةِ، وسيّئاتك بالمغفرةِ إن تبت؛ فلا تحقر عملًا صالحًا، ولا تقنط من مغفرةِ الله؛ فمن أحسن العملَ ورجا فضلَ الله نال أجره موفًّى وزيادة؛ فاجعل رجاءك في فضلِ الغفورِ الشكورِ عظيمًا؛ فهو يشكر القليلَ ويعطي الجزيل، ويغفر الكثيرَ ويستر العيب؛ فاعمل له، وارجُ فضله، وأبشر بكرمه؛ فالغفورُ الشكورُ لا يضيع أجرَ من أحسن عملًا."}}]},{"title":"ميراثُ الكتابِ وأصنافُ الأمّة، وجزاءُ المؤمنين والكافرين","range":[31,38],"theme":"حقّيّةُ القرآنِ وتصديقُه لما قبله، ووراثةُ الكتابِ وأصنافُ الأمّةِ الثلاثة، ونعيمُ جنّاتِ عدنٍ وحمدُ أهلها على إذهابِ الحزن، وعذابُ الكافرين الدائمُ وندمُهم وطلبُهم الرجعة، وأنّ الله عالمُ الغيبِ وذاتِ الصدور","verses":[{"n":31,"reflection":{"text":"«والذي أوحينا إليك من الكتاب هو الحق مصدقا لما بين يديه إن الله بعباده لخبير بصير» — والذي أوحينا إليك من القرآنِ هو الحقُّ مصدّقًا لما قبله من الكتب، إنّ الله بعباده لخبيرٌ بصير؛ ففي هذا تقريرُ حقّيّةِ القرآنِ وتصديقه للكتبِ السابقة؛ فأيقن بأنّ القرآنَ هو الحقُّ المصدّقُ لما قبله، فعظّمه واعمل به، واعلم أنّ الله خبيرٌ بصيرٌ بأحوالك، فراقبه في تعاملك مع كتابه، فمصدرُ القرآنِ الحقُّ يوجب التصديقَ والعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الخبير","البصير"],"heart_state":{"text":"اليقينُ بحقّيّةِ القرآنِ والعملُ به، ومراقبةُ الخبيرِ البصير."},"action":{"text":"أيقن بأنّ القرآنَ الذي أُوحي إلى النبيِّ ﷺ هو الحقُّ الثابتُ المصدّقُ لما قبله من الكتبِ السماوية «والذي أوحينا إليك من الكتاب هو الحق مصدقا لما بين يديه»؛ فعظّم القرآنَ في قلبك، واعمل بأحكامه، وتلقَّ آياته بالتصديقِ والإذعان؛ واعلم أنّ الله خبيرٌ بصيرٌ بأحوالِ عباده الظاهرةِ والباطنة، لا يخفى عليه شيء؛ فراقبه في تعاملك مع كتابه: في تلاوتك وتدبّرك وعملك؛ فمن أيقن بحقّيّةِ القرآنِ أقبل عليه؛ ومن راقب الله الخبيرَ البصيرَ أحسن عمله؛ فاجعل القرآنَ إمامك، واثقًا بأنه الحقُّ من عند الله؛ وأحسن التعاملَ معه مراقبًا لله الذي يعلم سرّك وعلنك؛ فمصدرُه الإلهيُّ يوجب تعظيمه، وإحاطةُ علمِ الله توجب مراقبته."}},{"n":32,"reflection":{"text":"«ثم أورثنا الكتاب الذين اصطفينا من عبادنا فمنهم ظالم لنفسه ومنهم مقتصد ومنهم سابق بالخيرات بإذن الله ذلك هو الفضل الكبير» — ثم أورثنا القرآنَ الذين اصطفيناهم من عبادنا (أمّةَ محمدٍ ﷺ)، فمنهم ظالمٌ لنفسه (بالتقصيرِ والمعاصي)، ومنهم مقتصدٌ (مؤدٍّ للواجباتِ تاركٌ للمحرّمات)، ومنهم سابقٌ بالخيراتِ بإذنِ الله (مجتهدٌ في الطاعات)، ذلك هو الفضلُ الكبير؛ ففي هذا أصنافُ الأمّةِ في التعاملِ مع الكتاب، وأنّ وراثتَه فضلٌ كبير؛ فاعلم أنّ الأمّةَ ثلاثةُ أصناف، فاجتهد أن تكون من السابقين بالخيرات، وإياك أن تكون من الظالمين لأنفسهم، فوراثةُ الكتابِ فضلٌ يستوجب العمل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاجتهادُ لتكون من السابقين بالخيرات، لا الظالمين لأنفسهم."},"action":{"text":"اعلم أنّ الله أورث أمّةَ محمدٍ ﷺ القرآنَ فضلًا واصطفاءً، وأنّ الأمّةَ في التعاملِ معه ثلاثةُ أصناف: ظالمٌ لنفسه بالتقصيرِ والمعاصي، ومقتصدٌ يؤدّي الواجباتِ ويترك المحرّمات، وسابقٌ بالخيراتِ بإذنِ الله يجتهد في الطاعاتِ ويتنافس في القُرَب «فمنهم ظالم لنفسه ومنهم مقتصد ومنهم سابق بالخيرات»؛ فاجتهد أن تكون من السابقين بالخيرات، أعلى الأصناف؛ وإن قصّرت فكن من المقتصدين؛ وإياك أن تكون من الظالمين لأنفسهم بالإصرارِ على المعاصي؛ فراجع نفسك: من أيِّ الأصنافِ أنت؟ واسعَ للارتقاءِ إلى الأعلى؛ فوراثةُ الكتابِ فضلٌ كبيرٌ يستوجب الشكرَ بالعمل؛ فبادر بالخيرات، وسابق إليها؛ فالسابقون هم المقرّبون؛ فاجعل همّك أن تكون في مقدّمةِ أهلِ الخير، لا في مؤخّرةِ المقصّرين."}},{"n":33,"reflection":{"text":"«جنات عدن يدخلونها يحلون فيها من أساور من ذهب ولؤلؤا ولباسهم فيها حرير» — جنّاتُ إقامةٍ دائمةٍ يدخلها هؤلاء الأصنافُ الثلاثة، يُحلَّون فيها من أساورَ من ذهبٍ ولؤلؤًا، ولباسهم فيها حرير؛ ففي هذا وصفُ نعيمِ أهلِ الجنّة؛ فاعمل لتدخل جنّاتِ عدنٍ وتنال حِلْيتها ولباسها، فنعيمُ الجنّةِ لا ينقطع، فاجتهد لتكون من أهلها، طامعًا في هذا النعيمِ المقيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لدخولِ جنّاتِ عدنٍ ونيلِ نعيمها المقيم."},"action":{"text":"اعمل الصالحاتِ لتدخل جنّاتِ عدنٍ (الإقامةِ الدائمة) التي وعد الله بها عباده المصطفين، وتنال فيها حِلْيتها من الأساورِ الذهبيةِ واللؤلؤ، ولباسها من الحرير «جنات عدن يدخلونها يحلون فيها من أساور من ذهب ولؤلؤا ولباسهم فيها حرير»؛ فنعيمُ الجنّةِ مقيمٌ لا ينقطع، وفيها ما لا عينٌ رأت ولا أذنٌ سمعت؛ فاجعل هذا النعيمَ العظيمَ حافزًا لك على الاجتهادِ في الطاعةِ والإكثارِ من الخيرات؛ فاجتهد لتكون من أهلها، طامعًا في هذا النعيمِ المقيم؛ فبادر بالأعمالِ الصالحةِ مبتغيًا وجهَ الله؛ فمن عمل للجنّةِ عملَ أهلها نالها؛ فالجنّةُ سلعةُ الله الغالية، ثمنُها الإيمانُ والعملُ الصالح؛ فاعمل لها عملَ من يرجو دخولها ونعيمها؛ فالنعيمُ الدائمُ يستحقّ أن تبذل له كلَّ جهدك."}},{"n":34,"reflection":{"text":"«وقالوا الحمد لله الذي أذهب عنا الحزن إن ربنا لغفور شكور» — وقال أهلُ الجنّةِ حين دخلوها: الحمدُ لله الذي أذهب عنا كلَّ حزنٍ وهمّ، إنّ ربّنا لغفورٌ لذنوبنا شكورٌ لأعمالنا؛ ففي هذا حمدُ أهلِ الجنّةِ على إذهابِ الأحزان؛ فارجُ الجنّةَ التي يُذهَب فيها كلُّ حزن، واحمد الله على نعمِه، فاجعل رجاءك في مغفرةِ الله وشكره، فهو الغفورُ الشكورُ الذي يُذهِب الأحزانَ عن أوليائه في الآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الشكور"],"heart_state":{"text":"رجاءُ الجنّةِ التي تُذهَب فيها الأحزان، وحمدُ الغفورِ الشكور."},"action":{"text":"ارجُ الجنّةَ التي يُذهِب الله فيها عن أهلها كلَّ حزنٍ وهمٍّ ونصَبٍ، حتى يقولوا حامدين: «الحمد لله الذي أذهب عنا الحزن»؛ فاعمل لتكون من أهلها؛ واحمد الله في الدنيا على نعمه، مقتديًا بأهلِ الجنّةِ في حمدهم؛ واجعل رجاءك في مغفرةِ الله وشكره، فهو الغفورُ الذي يغفر الذنوب، الشكورُ الذي يثيب على العمل ويضاعفه؛ فمن رجا الجنّةَ ومغفرةَ الله عمل لهما؛ فاستحضر ذلك اليومَ العظيم حين يُذهَب عن أهلِ الجنّةِ كلُّ حزن؛ فليكن ذلك حافزًا لك على الصبرِ على أحزانِ الدنيا وهمومها، رجاءَ يومٍ تُذهَب فيه كلُّ الأحزان؛ فأحزانُ الدنيا زائلة، ونعيمُ الجنّةِ دائم؛ فاصبر واعمل، وارجُ رحمةَ الغفورِ الشكور؛ فمن دخل الجنّةَ نسي كلَّ حزنٍ وهمّ."}},{"n":35,"reflection":{"text":"«الذي أحلنا دار المقامة من فضله لا يمسنا فيها نصب ولا يمسنا فيها لغوب» — الذي أنزلنا دارَ الإقامةِ الدائمةِ من فضله لا بأعمالنا، لا يصيبنا فيها تعبٌ ولا إعياء؛ ففي هذا أنّ دخولَ الجنّةِ بفضلِ الله، وأنها دارُ راحةٍ لا تعبَ فيها؛ فاعمل للجنّةِ راجيًا فضلَ الله لا معتمدًا على عملك، فدخولها بفضلِ الله ورحمته، وهي دارُ راحةٍ دائمةٍ لا نصبَ فيها ولا إعياء، فارجُ فضلَ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"رجاءُ دخولِ الجنّةِ بفضلِ الله، وأنها دارُ راحةٍ لا نصبَ فيها."},"action":{"text":"اعلم أنّ دخولَ الجنّةِ إنما هو بفضلِ الله ورحمته لا بمجرّدِ العمل، كما قال أهلها: «أحلنا دار المقامة من فضله»؛ فاعمل للجنّةِ راجيًا فضلَ الله وكرمه، لا معتمدًا على عملك؛ فالعملُ سببٌ، والفضلُ من الله؛ واعلم أنّ الجنّةَ دارُ إقامةٍ دائمةٍ وراحةٍ لا يمسّ أهلها فيها تعبٌ ولا إعياءٌ ولا نصب «لا يمسنا فيها نصب ولا يمسنا فيها لغوب»؛ فبعد تعبِ الدنيا ونصَبها راحةٌ دائمةٌ في الجنّة؛ فاصبر على تعبِ الطاعةِ في الدنيا، رجاءَ راحةِ الجنّةِ الدائمة؛ فمن تعب في طاعةِ الله قليلًا استراح في الجنّةِ أبدًا؛ فاجعل رجاءك في فضلِ الله عظيمًا؛ واعمل للجنّةِ عملَ من يرجو فضلَ الله ورحمته؛ فالفضلُ بيده، والراحةُ الدائمةُ في جنّته؛ فاطلبها بالعملِ والرجاء."}},{"n":36,"reflection":{"text":"«والذين كفروا لهم نار جهنم لا يقضى عليهم فيموتوا ولا يخفف عنهم من عذابها كذلك نجزي كل كفور» — والذين كفروا لهم نارُ جهنمَ خالدين فيها، لا يُقضى عليهم بالموتِ فيستريحوا، ولا يُخفَّف عنهم من عذابها، كذلك نجزي كلَّ كفورٍ جحود؛ ففي هذا شدّةُ عذابِ الكافرين ودوامه؛ فاحذر الكفرَ فجزاؤه نارٌ لا موتَ فيها ولا تخفيف، فاعمل صالحًا لتنجو من هذا المصير، ولا تكن من الكفورِ الجاحد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكفرِ الموجبِ لعذابٍ دائمٍ لا موتَ فيه ولا تخفيف."},"action":{"text":"احذر الكفرَ والجحودَ، فإنّ جزاء الكافرين نارُ جهنمَ خالدين فيها أبدًا، لا يُقضى عليهم بالموتِ فيستريحوا من العذاب، ولا يُخفَّف عنهم شيءٌ من عذابها «لا يقضى عليهم فيموتوا ولا يخفف عنهم من عذابها»؛ فهو عذابٌ دائمٌ لا انقطاعَ له ولا تخفيف؛ كذلك يجزي الله كلَّ كفورٍ جاحدٍ لنعمه؛ فاحذر أن تكون من الكفورِ الجاحد؛ واعمل الصالحاتِ مع الإيمانِ لتنجو من هذا المصيرِ الأليم؛ فبادر بالتوبةِ من كلِّ كفرٍ وجحود؛ فالنارُ دارُ الكافرين، عذابها دائمٌ شديدٌ لا يخفّف؛ فاجتهد أن تكون من أهلِ الجنّةِ لا من أهلِ النار؛ فاشكر نعمَ الله ولا تجحدها؛ فالشكورُ ينجو، والكفورُ يُجزى بعذابٍ لا ينقطع؛ فاجعل همّك النجاةَ من هذا العذاب، بالإيمانِ والعملِ والشكر."}},{"n":37,"reflection":{"text":"«وهم يصطرخون فيها ربنا أخرجنا نعمل صالحا غير الذي كنا نعمل أولم نعمركم ما يتذكر فيه من تذكر وجاءكم النذير فذوقوا فما للظالمين من نصير» — وهم يستغيثون في النارِ صارخين: ربّنا أخرجنا نعمل صالحًا غيرَ الذي كنا نعمل، فيقال لهم: أولم نمهلكم عمرًا يتذكّر فيه من تذكّر، وجاءكم النذيرُ (الرسولُ)؟ فذوقوا العذابَ فما للظالمين من نصير؛ ففي هذا ندمُ الكافرين وطلبهم الرجعةَ حين لا تنفع، وأنّ الله أعذر بالعمرِ والنذير؛ فبادر بالعملِ الصالحِ في عمرك قبل أن تطلب الرجعةَ فلا تُعطاها، فالله أمهلك عمرًا وأرسل إليك النذير، فلا حجّةَ لك، فاغتنم عمرك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ العمرِ بالعملِ الصالحِ قبل ندمِ يومٍ لا تنفع فيه الرجعة."},"action":{"text":"اغتنم عمرك بالعملِ الصالحِ والتوبةِ من الآن، قبل أن يأتيَ يومٌ يصطرخ فيه الكافرون في النارِ طالبين الرجعةَ ليعملوا صالحًا فلا يُعطونها «ربنا أخرجنا نعمل صالحا»؛ فيُقال لهم توبيخًا: أولم نمهلكم عمرًا يكفي للتذكّرِ والاتّعاظ، وجاءكم النذيرُ فأعذرنا إليكم؟ «أولم نعمركم ما يتذكر فيه من تذكر وجاءكم النذير»؛ فقد أقام الله الحجّةَ عليك بأمرين: العمرِ الذي أمهلك فيه، والنذيرِ الذي بلّغك؛ فلا حجّةَ لك في التقصير؛ فبادر بالعملِ الصالحِ في زمنِ الإمهال؛ ولا تسوّف حتى يفوت الأوان؛ فالظالمون يومئذٍ لا نصيرَ لهم؛ فاعمل لنفسك قبل أن تندم؛ فمن اغتنم عمره في الطاعةِ نجا، ومن فرّط ندم يومَ لا ينفع الندم؛ فعمرك رأسُ مالك، والنذيرُ قد بلّغك، فلا عذرَ بعد ذلك؛ فبادر بالعملِ الصالحِ قبل انقضاءِ الأجل."}},{"n":38,"reflection":{"text":"«إن الله عالم غيب السماوات والأرض إنه عليم بذات الصدور» — إنّ الله عالمُ غيبِ السماواتِ والأرض، إنه عليمٌ بما تخفيه الصدورُ من النيّاتِ والخواطر؛ ففي هذا تقريرُ إحاطةِ علمِ الله بالغيبِ وبما في الصدور؛ فراقب الله العالمَ بالغيبِ وبما في صدرك، فطهّر قلبك ونيّتك، فمن أيقن أنّ الله يعلم خفايا صدره أصلح سريرته، وعالمُ الغيبِ لا تخفى عليه خافية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله العالمِ بالغيبِ وبما في الصدور، وتطهيرُ القلب."},"action":{"text":"راقب الله في قلبك وسريرتك، فإنه عالمُ غيبِ السماواتِ والأرض، عليمٌ بما تخفيه الصدورُ من النيّاتِ والخواطرِ والمقاصد «إنه عليم بذات الصدور»؛ فطهّر قلبك من النيّاتِ الفاسدةِ والخواطرِ السيّئةِ كالغلِّ والحسدِ والحقدِ والرياء؛ فمن أيقن أنّ الله يعلم خفايا صدره اجتهد في إصلاحِ باطنه كظاهره؛ فالعبرةُ بصلاحِ القلبِ لا بمظهرِ العمل؛ فتعاهد قلبك بالتطهيرِ والإخلاص؛ فعالمُ الغيبِ والشهادةِ لا يعزب عنه مثقالُ ذرّة؛ فأصلح سريرتك تصلح علانيتك؛ ولا تُظهِر خيرًا وتُبطِن شرًّا؛ فالله مطّلعٌ على قلبك؛ فاجعل نيّاتك خالصةً لله، وقلبك طاهرًا من كلِّ سوء؛ فمن راقب عالمَ الغيبِ في قلبه، أصلح الله سرّه وعلنه؛ فطهارةُ القلبِ أساسُ قبولِ العمل."}}]},{"title":"الاستخلاف، وبطلانُ الشركاء، وإمساكُ الكون، وثباتُ سننِ الله","range":[39,45],"theme":"نعمةُ الاستخلافِ وأنّ الكفرَ يزيد مقتًا وخسارًا، وإبطالُ الشركِ بانتفاءِ مستنده، وإمساكُ الله للسماواتِ والأرض، وذمُّ نقضِ العهد، وأنّ المكرَ السيّئَ يحيق بأهله وسننَ الله لا تتبدّل، والاعتبارُ بالأقوياءِ الهالكين، وسعةُ حلمِ الله وإمهاله","verses":[{"n":39,"reflection":{"text":"«هو الذي جعلكم خلائف في الأرض فمن كفر فعليه كفره ولا يزيد الكافرين كفرهم عند ربهم إلا مقتا ولا يزيد الكافرين كفرهم إلا خسارا» — هو الذي جعلكم خلفاءَ في الأرضِ يخلف بعضكم بعضًا، فمن كفر فوبالُ كفره عليه، ولا يزيد الكافرين كفرهم عند ربّهم إلا بغضًا ومقتًا، ولا يزيدهم كفرهم إلا خسارًا؛ ففي هذا أنّ الاستخلافَ نعمةٌ ومسؤولية، وأنّ الكفرَ يزيد صاحبه مقتًا وخسارًا؛ فاشكر نعمةَ الاستخلافِ باستعمارِ الأرضِ بالطاعة، واحذر الكفرَ فإنه يزيد صاحبه مقتًا عند الله وخسارًا، فالإيمانُ ربحٌ والكفرُ خسار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الاستخلافِ بالطاعة، والحذرُ من الكفرِ المُخسِر."},"action":{"text":"اشكر نعمةَ الله في جعلك من الخلائفِ في الأرضِ يخلف بعضكم بعضًا؛ فاستعمر الأرضَ بطاعةِ الله وعبادته لا بمعصيته «هو الذي جعلكم خلائف في الأرض»؛ واعلم أنّ من كفر فوبالُ كفره عليه وحده، وأنّ الكفرَ لا يزيد صاحبه عند الله إلا مقتًا وبغضًا، ولا يزيده إلا خسارًا في الدنيا والآخرة «ولا يزيد الكافرين كفرهم عند ربهم إلا مقتا... إلا خسارا»؛ فاحذر الكفرَ والمعصية، فإنهما خسارٌ ومقت؛ والزم الإيمانَ والطاعة، فإنهما ربحٌ ورضا؛ فوظّف استخلافك في الأرضِ في عمارتها بالخيرِ والطاعة؛ فمن آمن وعمل صالحًا ربح ونال رضا الله، ومن كفر وعصى خسر ونال مقته؛ فاجعل حياتك في الأرضِ عمارةً بالطاعةِ لا إفسادًا بالمعصية؛ فالاستخلافُ أمانةٌ ومسؤولية؛ فأدِّها بالإيمانِ والعملِ الصالح."}},{"n":40,"reflection":{"text":"«قل أرأيتم شركاءكم الذين تدعون من دون الله أروني ماذا خلقوا من الأرض أم لهم شرك في السماوات أم آتيناهم كتابا فهم على بينت منه بل إن يعد الظالمون بعضهم بعضا إلا غرورا» — قل للمشركين: أخبروني عن شركائكم الذين تدعونهم من دونِ الله، أروني ماذا خلقوا من الأرض؟ أم لهم شركةٌ في خلقِ السماوات؟ أم آتيناهم كتابًا فهم على حجّةٍ منه؟ بل ما يعد الظالمون بعضهم بعضًا إلا غرورًا وباطلًا؛ ففي هذا إبطالُ الشركِ بانتفاءِ كلِّ مستندٍ له؛ فاعلم أنّ الشركَ لا مستندَ له: لا خلقٌ ولا شركةٌ ولا كتاب، بل هو غرورٌ وباطل، فأخلص التوحيدَ لله، ولا تعبد من لا يخلق ولا يملك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إبطالُ الشركِ بانتفاءِ كلِّ مستندٍ له، وإخلاصُ التوحيد."},"action":{"text":"اعلم أنّ الشركَ باطلٌ لا مستندَ له من أيِّ وجه: فما خلق شركاؤهم شيئًا من الأرض، ولا لهم شركةٌ في خلقِ السماوات، ولا آتاهم الله كتابًا يؤيّد شركهم «أروني ماذا خلقوا من الأرض أم لهم شرك في السماوات»؛ فالشركُ غرورٌ وباطلٌ يعد به الظالمون بعضهم بعضًا «إن يعد الظالمون بعضهم بعضا إلا غرورا»؛ فأخلص التوحيدَ لله وحده؛ ولا تعبد من لا يخلق ولا يملك ولا سندَ لعبادته؛ فاصرف عبادتك ودعاءك وتوكّلك إلى الله الخالقِ المالك؛ فمن عبد غيرَ الله فقد عبد من لا حجّةَ لعبادته؛ فحقّق التوحيدَ القائمَ على البرهان؛ ولا تتّبع في دينك غرورًا ولا باطلًا؛ فالحقُّ ما قام عليه الدليل، والشركُ باطلٌ لا سندَ له؛ فاجعل عبادتك كلَّها لله وحده؛ فهو الخالقُ المالكُ المستحقُّ للعبادة."}},{"n":41,"reflection":{"text":"«إن الله يمسك السماوات والأرض أن تزولا ولئن زالتا إن أمسكهما من أحد من بعده إنه كان حليما غفورا» — إنّ الله يمسك السماواتِ والأرضَ أن تزولا عن أماكنهما، ولئن زالتا ما أمسكهما أحدٌ من بعده، إنه كان حليمًا غفورًا؛ ففي هذا تقريرُ قدرةِ الله في إمساكِ الكون، وحلمِه ومغفرته؛ فتأمّل قدرةَ الله الممسكِ للسماواتِ والأرض، فلولا إمساكه لزالتا، فاعتمد على القادرِ الذي بيده الكون، واعلم أنه حليمٌ غفورٌ يمهل ويستر، فاشكر حلمه ولا تغترَّ به.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الحليم","الغفور"],"heart_state":{"text":"التأمّلُ في إمساكِ الله للكون، وشكرُ حلمِه ومغفرته."},"action":{"text":"تأمّل عظيمَ قدرةِ الله في إمساكه السماواتِ والأرضَ أن تزولا عن أماكنهما وتنهار، فلولا إمساكه لهما لزالتا وما أمسكهما أحدٌ من بعده «إن الله يمسك السماوات والأرض أن تزولا»؛ فالكونُ كلُّه قائمٌ بقدرةِ الله وإمساكه؛ فاعتمد على القادرِ الذي بيده مقاليدُ الكونِ كلِّه؛ واعلم أنه حليمٌ لا يعاجل العصاةَ بالعقوبة، غفورٌ يستر ويعفو عمّن تاب «إنه كان حليما غفورا»؛ فاشكر حلمَ الله الذي أمهلك، ومغفرته التي وسعتك؛ ولا تغترَّ بحلمه فتتمادى في المعصية؛ بل اجعل حلمه داعيًا لك إلى التوبةِ والإنابة؛ فمن تأمّل قدرةَ الله في إمساكِ الكونِ عظّمه وتوكّل عليه؛ ومن عرف حلمه ومغفرته بادر بالتوبةِ شكرًا وحياءً؛ فالله يمسك الكونَ بقدرته، ويمهل العبادَ بحلمه، ويغفر لهم بمغفرته؛ فاشكر واعبد وتُب."}},{"n":42,"reflection":{"text":"«وأقسموا بالله جهد أيمانهم لئن جاءهم نذير ليكونن أهدى من إحدى الأمم فلما جاءهم نذير ما زادهم إلا نفورا» — وأقسم المشركون بالله مجتهدين في أيمانهم: لئن جاءهم نذيرٌ ليكونُنّ أهدى من اليهودِ والنصارى، فلما جاءهم النذيرُ (محمدٌ ﷺ) ما زادهم مجيئه إلا نفورًا عن الحق؛ ففي هذا ذمُّ نقضِ العهدِ ومخالفةِ القولِ للفعل؛ فاحذر أن تعِد وعدًا ثم تخلفه، أو تقسم يمينًا ثم تنقضها، فالمشركون أقسموا ليؤمنن فلما جاءهم الحقُّ نفروا، فكن صادقًا في عهدك، موافقًا قولك فعلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من نقضِ العهدِ ومخالفةِ القولِ للفعل."},"action":{"text":"احذر أن تعِد وعدًا أو تقسم يمينًا ثم تنقضها وتخالفها، كما فعل المشركون الذين أقسموا بالله جهدَ أيمانهم أنهم لو جاءهم نذيرٌ لكانوا أهدى الأمم، فلما جاءهم النذيرُ ما زادهم إلا نفورًا وإعراضًا «فلما جاءهم نذير ما زادهم إلا نفورا»؛ فهذا نقضٌ للعهدِ ومخالفةٌ للقولِ بالفعل؛ فكن صادقًا في عهدك ووعدك ويمينك، موافقًا قولك فعلك؛ ولا تقل ما لا تفعل؛ فمن وعد بالخيرِ إذا جاءه ثم أعرض عنه فقد نقض عهده وخالف قوله؛ فراقب نفسك: هل توافق أفعالُك أقوالك؟ فاحذر أن تكون ممّن يتمنّى الهدى فإذا جاءه نفر منه؛ فإذا تبيّن لك الحقُّ فبادر باتّباعه، ولا تنفر منه؛ فالصدقُ أن يوافق القولُ الفعل، والعهدُ أن يُوفى به؛ فكن صادقًا في عهدك مع الله ومع الناس."}},{"n":43,"reflection":{"text":"«استكبارا في الأرض ومكر السيئ ولا يحيق المكر السيئ إلا بأهله فهل ينظرون إلا سنت الأولين فلن تجد لسنت الله تبديلا ولن تجد لسنت الله تحويلا» — نفروا استكبارًا في الأرضِ ومكرًا سيّئًا، ولا يحيق المكرُ السيّئُ إلا بأهله، فهل ينتظرون إلا سنّةَ الله في الأوّلين (من الإهلاك)؟ فلن تجد لسنّةِ الله تبديلًا ولن تجد لها تحويلًا؛ ففي هذا أنّ الاستكبارَ والمكرَ يعودان على أهلهما، وأنّ سننَ الله ثابتة؛ فاحذر الاستكبارَ والمكرَ السيّئ، فإنهما يعودان على صاحبهما، واعلم أنّ سننَ الله لا تتبدّل، فمن استكبر ومكر أهلكه الله كما أهلك من قبله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستكبارِ والمكرِ السيّئِ العائدِ على أهله، وثباتُ سننِ الله."},"action":{"text":"احذر الاستكبارَ في الأرضِ والمكرَ السيّئ، فإنّ الاستكبارَ عن الحقِّ سببُ الهلاك، والمكرَ السيّئَ لا يحيق ولا يعود إلا على صاحبه «ولا يحيق المكر السيئ إلا بأهله»؛ فمن مكر بالحقِّ وأهله عاد مكره عليه؛ ومن استكبر عن قبولِ الحقِّ أهلكه كبره؛ واعلم أنّ سننَ الله في إهلاكِ المستكبرين الماكرين ثابتةٌ لا تتبدّل ولا تتحوّل «فلن تجد لسنت الله تبديلا ولن تجد لسنت الله تحويلا»؛ فمن سلك سبيلَ المستكبرين الماكرين لحقه ما لحقهم؛ فتواضع للحقِّ واقبله، ولا تمكر بأحد؛ فالبغيُ والمكرُ مصرعُ أهلهما؛ فالزم الاستقامةَ والصدقَ، واجتنب الكبرَ والكيد؛ فسننُ الله عادلةٌ ثابتة؛ فمن استكبر ومكر أُهلِك، ومن تواضع وأخلص نجا؛ فاجعل عملك موافقًا لسننِ الله في النجاةِ لا في الهلاك."}},{"n":44,"reflection":{"text":"«أولم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم وكانوا أشد منهم قوة وما كان الله ليعجزه من شيء في السماوات ولا في الأرض إنه كان عليما قديرا» — أولم يسيروا في الأرضِ فينظروا كيف كانت عاقبةُ الذين من قبلهم، وكانوا أشدَّ منهم قوّة؟ وما كان الله ليعجزه شيءٌ في السماواتِ ولا في الأرض، إنه كان عليمًا قديرًا؛ ففي هذا الاعتبارُ بعاقبةِ الأقوياءِ المكذّبين، وأنّ الله لا يعجزه شيء؛ فاعتبر بمصارعِ الأقوياءِ الذين أهلكهم الله، فلا تغني قوّةٌ عن أهلها، واعلم أنّ الله لا يعجزه شيء، فهو العليمُ القدير، فلا تأمن عقوبته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العليم","القدير"],"heart_state":{"text":"الاعتبارُ بعاقبةِ الأقوياءِ المكذّبين، وأنّ الله لا يعجزه شيء."},"action":{"text":"اعتبر بعاقبةِ الأممِ التي كانت أشدَّ قوّةً من قومك، فأهلكها الله لمّا كذّبت رسلها «وكانوا أشد منهم قوة»؛ فلا تغترَّ بقوّةٍ أو حضارةٍ فتظنّها تعصمك من عذابِ الله؛ فما أغنت القوّةُ عن أصحابها شيئًا حين نزل بهم أمرُ الله؛ واعلم أنّ الله لا يعجزه شيءٌ في السماواتِ ولا في الأرض، فهو العليمُ بكلِّ شيء، القديرُ على كلِّ شيء «إنه كان عليما قديرا»؛ فلا يفوته أحدٌ ولا يعجزه شيء؛ فلا تأمن عقوبةَ الله باغترارك بقوّةٍ أو مال؛ بل اتّقِ الله وراقبه؛ فمن اعتبر بمصارعِ الأقوياءِ الهالكين تجنّب سبيلهم؛ واجعل من أخبارِ الأممِ عبرةً تزيدك خشيةً لله وحذرًا من معصيته؛ فالله عليمٌ قديرٌ لا يعجزه شيء؛ فالعاقبةُ للمتّقين، والدمارُ للمكذّبين مهما بلغت قوّتهم."}},{"n":45,"reflection":{"text":"«ولو يؤاخذ الله الناس بما كسبوا ما ترك على ظهرها من دابة ولكن يؤخرهم إلى أجل مسمى فإذا جاء أجلهم فإن الله كان بعباده بصيرا» — ولو يعاقب الله الناسَ بذنوبهم عاجلًا ما ترك على ظهرِ الأرضِ دابّةً، ولكن يؤخّرهم إلى أجلٍ محدّد، فإذا جاء أجلهم فإنّ الله كان بعباده بصيرًا يجازيهم بأعمالهم؛ ففي هذا سعةُ حلمِ الله وإمهاله؛ فاشكر حلمَ الله وإمهاله، ولا تغترَّ به، فلولا حلمه لأهلك الناسَ بذنوبهم، فاغتنم مهلةَ الإمهالِ بالتوبةِ والعمل، فالله بصيرٌ بك يجازيك عند أجلك.","source":"تفسير السعدي","grade":"ma'thur"},"names":["البصير"],"heart_state":{"text":"شكرُ حلمِ الله وإمهاله، واغتنامُ المهلةِ بالتوبةِ والعمل."},"action":{"text":"اشكر حلمَ الله وسعةَ إمهاله، فلولا حلمه لعاقب الناسَ بذنوبهم عاجلًا حتى ما يترك على ظهرِ الأرضِ دابّة «ولو يؤاخذ الله الناس بما كسبوا ما ترك على ظهرها من دابة»؛ لكنه يؤخّرهم بحلمه إلى أجلٍ مسمًّى؛ فلا تغترَّ بهذا الإمهال فتتمادى في المعصية؛ بل اغتنم مهلةَ الحياةِ بالتوبةِ والعملِ الصالح؛ فإذا جاء أجلك جازاك الله بعملك، فهو بصيرٌ بك لا يخفى عليه شيءٌ من أحوالك «فإذا جاء أجلهم فإن الله كان بعباده بصيرا»؛ فبادر بالتوبةِ والعملِ في زمنِ الإمهال؛ ولا تجعل حلمَ الله سببًا لجرأتك على معصيته؛ بل اجعله داعيًا لشكره والإنابةِ إليه؛ فمن اغتنم مهلةَ الإمهالِ بالتوبةِ نجا، ومن اغترّ بها وأصرَّ أُخِذ عند أجله؛ فاختم سورتك بالتوبةِ واغتنامِ العمرِ في طاعةِ الله؛ فالله حليمٌ يمهل، بصيرٌ يحاسب."}}]}],"coverage":{"covered":45,"total":45}};
